// Some portions generated by Claude Code
package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;

class InterruptingTimeLimitTest {

	@Test
	void blockedOwnerIsInterruptedAndTheFlagIsClearedOnClose() {
		CountDownLatch never = new CountDownLatch(1);
		long started = System.nanoTime();
		InterruptingTimeLimit limit = InterruptingTimeLimit.start(100);
		try {
			assertThrows(InterruptedException.class, () -> never.await(5, TimeUnit.SECONDS));
			assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started) >= 90);
			// Code that cannot propagate the InterruptedException restores the flag.
			Thread.currentThread().interrupt();
		} finally {
			limit.close();
		}
		assertTrue(limit.fired());
		assertFalse(Thread.currentThread().isInterrupted(), "close must clear the interrupt the time limit delivered");
		assertTrue(limit.remainingMillis() <= 0);
	}

	@Test
	void closingBeforeTheLimitNeverInterruptsTheOwner() throws Exception {
		InterruptingTimeLimit limit = InterruptingTimeLimit.start(100);
		assertTrue(limit.remainingMillis() > 0);
		limit.close();
		Thread.sleep(250);
		assertFalse(limit.fired());
		assertFalse(Thread.interrupted(), "a closed time limit must not interrupt a later task on the thread");
	}

	@Test
	void nonPositiveLimitInterruptsAtOnce() {
		try (InterruptingTimeLimit limit = InterruptingTimeLimit.start(0)) {
			assertTrue(limit.fired());
			assertTrue(Thread.currentThread().isInterrupted());
		}
		assertFalse(Thread.currentThread().isInterrupted());
	}

	@Test
	void anInterruptDeliveredByAnotherPartyIsKeptWhenTheLimitDidNotFire() {
		InterruptingTimeLimit limit = InterruptingTimeLimit.start(TimeUnit.HOURS.toMillis(1));
		Thread.currentThread().interrupt();
		limit.close();
		assertTrue(Thread.interrupted(), "only interrupts delivered by the time limit are cleared");
	}
}
